### Option B — **ESP scans and sends results over serial → UNO prints / drives LEDs**
ESP does the scan, sends a simple CSV or JSON line over serial. UNO reads serial and prints to Serial Monitor (or lights LEDs to show signal strength). Use this if you want Arduino involved or want LED indicators.

**ESP code (serial output)**

```cpp
// ESP-01 WiFi scanner that sends CSV lines over Serial
#include <ESP8266WiFi.h>

void setup() {
  Serial.begin(115200);
  delay(100);
  Serial.println("ESP_SCAN_READY");
  delay(200);
}

void loop() {
  int n = WiFi.scanNetworks();
  // Format: SSID,RSSI,CHANNEL,ENC
  for (int i = 0; i < n; i++) {
    String ssid = WiFi.SSID(i);
    int rssi = WiFi.RSSI(i);
    int ch = WiFi.channel(i);
    String enc = (WiFi.encryptionType(i) == ENC_TYPE_NONE) ? "OPEN" : "ENC";
    // Escape commas in SSID
    ssid.replace(",", "_");
    Serial.print(ssid);
    Serial.print(",");
    Serial.print(rssi);
    Serial.print(",");
    Serial.print(ch);
    Serial.print(",");
    Serial.println(enc);
    delay(10);
  }
  Serial.println("SCAN_DONE");
  delay(5000); // wait 5s between scans
}
```

**UNO code (read serial and print + LED demo)**  
Connect ESP TX → UNO RX, ESP RX → UNO TX, common GND. UNO is powered from USB; ESP powered by 3.3V regulator.

```cpp
// UNO: Read serial from ESP and print to Serial Monitor; simple LED bar
const int LED1 = 8; // low signal indicator
const int LED2 = 9;
const int LED3 = 10; // strong signal
String line = "";

void setup() {
  Serial.begin(115200); // PC monitor
  Serial1.begin(115200); // on UNO there's only one hardware Serial; if using UNO, Serial1 not available.
  // NOTE: If using UNO, you must use SoftwareSerial to read from ESP.
  pinMode(LED1, OUTPUT); pinMode(LED2, OUTPUT); pinMode(LED3, OUTPUT);
  digitalWrite(LED1, LOW); digitalWrite(LED2, LOW); digitalWrite(LED3, LOW);
}

// For UNO we need SoftwareSerial:
#include <SoftwareSerial.h>
SoftwareSerial espSerial(2, 3); // RX, TX (connect UNO pin2->ESP TX, UNO pin3->ESP RX)

void loop() {
  if (espSerial.available()) {
    String s = espSerial.readStringUntil('\n');
    s.trim();
    if (s.length() == 0) return;
    if (s == "SCAN_DONE" || s == "ESP_SCAN_READY") {
      Serial.println(s);
      return;
    }
    // expected CSV: SSID,RSSI,CH,ENC
    Serial.println("ESP: " + s);
    // parse RSSI
    int firstComma = s.indexOf(',');
    int secondComma = s.indexOf(',', firstComma + 1);
    if (firstComma > 0 && secondComma > firstComma) {
      String rssiStr = s.substring(firstComma + 1, secondComma);
      int rssi = rssiStr.toInt();
      // Map RSSI to LED levels (example thresholds)
      digitalWrite(LED1, LOW); digitalWrite(LED2, LOW); digitalWrite(LED3, LOW);
      if (rssi > -60) digitalWrite(LED3, HIGH); // strong
      else if (rssi > -75) digitalWrite(LED2, HIGH); // medium
      else digitalWrite(LED1, HIGH); // weak
    }
  }
}
```

**Notes on UNO code:** UNO has only one hardware serial (pins 0/1) which is used by USB. So use `SoftwareSerial` (as above) or temporarily remove the ATmega while flashing if you want to use hardware serial. The example uses pins 2 (RX) and 3 (TX) for `SoftwareSerial`. Wire ESP TX → UNO pin2, ESP RX → UNO pin3. Keep baud at 115200 — `SoftwareSerial` is unreliable at high baud; if it fails, lower ESP baud to 9600 (change `Serial.begin(115200)` to `Serial.begin(9600)` in ESP code before flashing).

