```cpp
// NodeMCU Wi-Fi Scanner (SoftAP + Web UI)
// Works on ESP8266 (NodeMCU / Wemos D1 mini)

#include <ESP8266WiFi.h>
#include <ESP8266WebServer.h>

ESP8266WebServer server(80);

// Translate encryption enum to human text
String encTypeToText(uint8_t t) {
  switch (t) {
    case ENC_TYPE_NONE: return "Open";
    case ENC_TYPE_WEP:  return "WEP";
    case ENC_TYPE_TKIP: return "WPA/TKIP";
    case ENC_TYPE_CCMP: return "WPA2/CCMP";
    case ENC_TYPE_AUTO: return "AUTO";
    default:            return "Unknown";
  }
}

String header() {
  return F(
    "<!doctype html><html><head><meta charset='utf-8'>"
    "<meta name='viewport' content='width=device-width,initial-scale=1'>"
    "<title>ESP8266 Wi-Fi Scanner</title>"
    "<style>body{font-family:system-ui;margin:16px}"
    "table{border-collapse:collapse;width:100%}"
    "th,td{border:1px solid #ccc;padding:6px;text-align:left}"
    "th{background:#f3f3f3}</style></head><body>"
    "<h2>ESP8266 Wi-Fi Scanner</h2>"
  );
}

String footer() {
  return F("<p style='color:#666;font-size:12px'>Passive scan only. Use on your own network.</p></body></html>");
}

String scanTable() {
  String s;
  int n = WiFi.scanComplete();
  if (n == WIFI_SCAN_RUNNING) {
    return F("<p>Scanning… refresh in a second.</p>");
  }
  if (n < 0) {
    n = WiFi.scanNetworks(); // blocking fallback
  }
  s += "<p>Found <b>" + String(n) + "</b> network(s). ";
  s += "<a href='/rescan'>Rescan</a></p>";
  s += F("<table><tr><th>#</th><th>SSID</th><th>RSSI (dBm)</th><th>Channel</th><th>Encryption</th></tr>");
  if (n == 0) {
    s += F("<tr><td colspan='5'>No networks</td></tr>");
  } else {
    for (int i = 0; i < n; i++) {
      s += "<tr><td>" + String(i + 1) + "</td>";
      s += "<td>" + WiFi.SSID(i) + "</td>";
      s += "<td>" + String(WiFi.RSSI(i)) + "</td>";
      s += "<td>" + String(WiFi.channel(i)) + "</td>";
      s += "<td>" + encTypeToText(WiFi.encryptionType(i)) + "</td></tr>";
    }
  }
  s += F("</table>");
  return s;
}

void handleRoot() {
  String page = header();
  page += "<p>Connect to AP: <b>" + WiFi.softAPSSID() + "</b> · IP: <b>" + WiFi.softAPIP().toString() + "</b></p>";
  page += scanTable();
  page += footer();
  server.send(200, "text/html", page);
}

void handleRescan() {
  WiFi.scanDelete();
  WiFi.scanNetworks(true, true); // async, show_hidden=true
  server.sendHeader("Location", "/");
  server.send(303); // See Other
}

void setup() {
  Serial.begin(115200);
  delay(100);

  // Start our own Wi-Fi network so no home Wi-Fi needed
  WiFi.mode(WIFI_AP_STA);  // AP + STA (STA idle but lets async scan work well)
  WiFi.softAP("ESP_Scanner"); // no password
  Serial.print("AP IP: ");
  Serial.println(WiFi.softAPIP());

  // Start an initial async scan
  WiFi.scanNetworks(true, true);

  // Web routes
  server.on("/", handleRoot);
  server.on("/rescan", handleRescan);
  server.begin();

  // On many boards LED_BUILTIN is active LOW; leave OFF initially
  pinMode(LED_BUILTIN, OUTPUT);
  digitalWrite(LED_BUILTIN, HIGH);
}

void loop() {
  server.handleClient();
}
```

