/*
   ESP32 Local Chat Server
   -----------------------
   The ESP32 creates its own Wi-Fi network called "ESP32_Chat".
   Connect any phone or PC to that network.
   Open  http://192.168.4.1  → you'll see a chat room page.
   Type a message → all connected users instantly see it.
*/

#include <WiFi.h>
#include <WebServer.h>
#include <WebSocketsServer.h>

WebServer server(80);
WebSocketsServer webSocket = WebSocketsServer(81);

const char* ssid = "ESP32_Chat";
const char* password = ""; // open network

// Basic HTML UI (served once at 192.168.4.1)
String pageHTML = R"rawliteral(
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>ESP32 Chat</title>
<style>
body { font-family: sans-serif; background:#f8f8f8; margin:10px; }
#chat { border:1px solid #ccc; background:white; height:60vh; overflow-y:auto; padding:10px; }
input { width:80%; padding:8px; }
button { padding:8px 12px; }
.msg { margin:4px 0; padding:4px; background:#e9e9ff; border-radius:5px; }
.sys { color:#777; font-size:0.9em; }
</style>
</head>
<body>
<h2>ESP32 Local Chat</h2>
<div id="chat"></div>
<br>
<input id="msg" placeholder="Type message..." onkeydown="if(event.key==='Enter') send();">
<button onclick="send()">Send</button>

<script>
var ws = new WebSocket("ws://" + window.location.host + ":81/");
ws.onmessage = function(e) {
  var chat = document.getElementById('chat');
  var div = document.createElement('div');
  div.innerHTML = e.data;
  if(e.data.startsWith('*')) { div.className = 'sys'; }
  else { div.className = 'msg'; }
  chat.appendChild(div);
  chat.scrollTop = chat.scrollHeight;
};

function send() {
  var i = document.getElementById('msg');
  if(i.value.trim() !== "") {
    ws.send(i.value);
    i.value = "";
  }
}
</script>
</body>
</html>
)rawliteral";

// Send HTML when user connects to the web page
void handleRoot() {
  server.send(200, "text/html", pageHTML);
}

// When a WebSocket event happens
void onWebSocketEvent(uint8_t num, WStype_t type, uint8_t * payload, size_t length) {
  switch(type) {
    case WStype_CONNECTED: {
      IPAddress ip = webSocket.remoteIP(num);
      Serial.printf("[%u] Connected from %s\n", num, ip.toString().c_str());
      String msg = "* User " + ip.toString() + " joined the chat";
      webSocket.broadcastTXT(msg);
      break;
    }
    case WStype_DISCONNECTED: {
      Serial.printf("[%u] Disconnected\n", num);
      webSocket.broadcastTXT("* A user left the chat");
      break;
    }
    case WStype_TEXT: {
      String msg = (const char *)payload;
      Serial.printf("[%u] Message: %s\n", num, msg.c_str());
      webSocket.broadcastTXT(msg); // send to all
      break;
    }
  }
}

void setup() {
  Serial.begin(115200);
  delay(100);
  Serial.println("Starting ESP32 Chat Server...");

  WiFi.mode(WIFI_AP);
  WiFi.softAP(ssid, password);
  Serial.print("AP IP address: ");
  Serial.println(WiFi.softAPIP());

  server.on("/", handleRoot);
  server.begin();

  webSocket.begin();
  webSocket.onEvent(onWebSocketEvent);

  Serial.println("Chat server ready. Connect to Wi-Fi 'ESP32_Chat' and open 192.168.4.1");
}

void loop() {
  server.handleClient();
  webSocket.loop();
}
